    <div class="status-container" id="statusContainer">
        <div class="status-header" id="statusHeader">
            <span class="name">白灵灵</span>
            <span class="arrow" id="arrowIcon">▼</span>
        </div>
        <div class="status-body" id="statusBody">
            <div class="loading" id="loadingText">正在加载...</div>
        </div>
    </div>

    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                console.error("无法获取消息内容");
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 逐行解析状态栏数据 ========== */
        function parseStatusData(messageText) {
            var result = {
                view: '',
                videoFrame: '',
                extraLabel: '',
                extraValue: ''
            };

            var tagMatch = messageText.match(/<status_bar>([\s\S]*?)<\/status_bar>/);
            if (!tagMatch || !tagMatch[1]) {
                console.error("未找到状态栏标签");
                return result;
            }

            var content = tagMatch[1];
            var lines = content.split('\n');

            var currentField = '';
            var fieldValues = {
                view: '',
                videoFrame: '',
                extraLabel: '',
                extraValue: ''
            };

            for (var i = 0; i < lines.length; i++) {
                var line = lines[i];

                /* 检查是否是字段标记行 [字段名|...] */
                var fieldMatch = line.match(/^\[([^\|]+)\|([\s\S]*)$/);
                if (fieldMatch) {
                    var fieldName = fieldMatch[1].trim();
                    var fieldBody = fieldMatch[2].trim();
                    /* 去掉可能的尾部 ] */
                    fieldBody = fieldBody.replace(/\]$/, '');

                    if (fieldName === '当前视角') {
                        currentField = 'view';
                    } else if (fieldName === '视频画面') {
                        currentField = 'videoFrame';
                    } else {
                        currentField = 'extra';
                        fieldValues.extraLabel = fieldName;
                    }

                    if (currentField === 'view') {
                        fieldValues.view = fieldBody;
                    } else if (currentField === 'videoFrame') {
                        fieldValues.videoFrame = fieldBody;
                    } else {
                        fieldValues.extraValue = fieldBody;
                    }
                } else {
                    /* 非字段标记行，作为上一个字段的继续 */
                    var trimmedLine = line.trim();
                    if (!trimmedLine) continue;

                    if (currentField === 'view') {
                        fieldValues.view += '\n' + trimmedLine;
                    } else if (currentField === 'videoFrame') {
                        fieldValues.videoFrame += '\n' + trimmedLine;
                    } else if (currentField === 'extra') {
                        fieldValues.extraValue += '\n' + trimmedLine;
                    }
                }
            }

            result.view = fieldValues.view;
            result.videoFrame = fieldValues.videoFrame;
            result.extraLabel = fieldValues.extraLabel;
            result.extraValue = fieldValues.extraValue;

            return result;
        }

        /* ========== 渲染界面 ========== */
        function renderPage(data) {
            var bodyEl = document.getElementById('statusBody');

            if (!data.view) {
                bodyEl.innerHTML = '<div class="loading">❌ 未找到视角信息</div>';
                return;
            }

            var isV1 = data.view.indexOf('视角一') !== -1;
            var isV2 = data.view.indexOf('视角二') !== -1;

            if (!isV1 && !isV2) {
                bodyEl.innerHTML = '<div class="loading">❌ 视角格式无法识别</div>';
                return;
            }

            var viewClass = isV1 ? 'v1' : 'v2';
            var viewText = isV1 ? '视角一 · 视频通话' : '视角二 · 调教视频';

            var extraLabel = data.extraLabel || (isV1 ? '可疑变化' : '变化由来');
            var extraValue = data.extraValue || '';

            var html = '';
            html += '<span class="view-tag ' + viewClass + '">' + viewText + '</span>';
            html += '<div class="info-block ' + viewClass + '">';
            html += '<div class="label">视频画面</div>';
            html += '<div class="text">' + (data.videoFrame || '') + '</div>';
            html += '</div>';
            html += '<div class="info-block ' + viewClass + '">';
            html += '<div class="label">' + extraLabel + '</div>';
            html += '<div class="text">' + extraValue + '</div>';
            html += '</div>';

            bodyEl.innerHTML = html;
        }

        /* ========== 展开收起交互 ========== */
        function setupToggle() {
            var header = document.getElementById('statusHeader');
            var body = document.getElementById('statusBody');
            var arrow = document.getElementById('arrowIcon');

            header.addEventListener('click', function() {
                var isShown = body.classList.contains('show');
                if (isShown) {
                    body.classList.remove('show');
                    arrow.classList.remove('expanded');
                } else {
                    body.classList.add('show');
                    arrow.classList.add('expanded');
                }
            });
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('statusBody').innerHTML =
                        '<div class="loading">❌ 无法获取消息内容</div>';
                    return;
                }
                var data = parseStatusData(messageText);
                renderPage(data);
                setupToggle();
            } catch (error) {
                console.error("错误:", error);
                document.getElementById('statusBody').innerHTML =
                    '<div class="loading">❌ 加载失败：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
